```use strict;
use warnings;

sub my_split_length {
    my ($string, $pattern) = @_;
    my @arr = split($pattern, $string);
    return scalar @arr;
}

warn my_split_length(',,', ','); # 0
warn my_split_length(',, ', ','); # 3
warn my_split_length(' ,,', ','); # 1
warn my_split_length(' ,, ', ','); # 3```
